package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.signal.Signal;
import com.pathland.view.state.State;

import java.util.ArrayList;
import java.util.List;

import static com.pathland.view.signal.Signals.computed;

/**
 * The music player demo root view — an Apple Music-style player authored purely
 * with the Java DSL: a track library (left), a now-playing sidebar with the
 * album art (right), and a bottom player bar with transport controls, a seek
 * slider, and a volume slider.
 *
 * <p>All state is app-owned {@link State} (persisted per-session); the renderer
 * only lays out the declarative tree. Track selection, prev/next, play/pause
 * and the sliders re-emit fine-grained {@code SET_TEXT}/{@code SET_PROPERTY}
 * deltas.
 */
public final class MusicPlayerView implements View {

    /** The seek slider's fixed range (seconds); every track fits inside. */
    private static final float SEEK_MAX = 240f;
    private static final float VOLUME_MAX = 100f;
    private static final int SIDEBAR_WIDTH = 280;
    private static final int BAR_HEIGHT = 76;

    private static final Color SECONDARY_FG = Color.rgb(0x6B, 0x72, 0x80);
    private static final Color ACTIVE_ROW_BG = Color.rgb(0xE8, 0xEF, 0xFF);
    private static final Color ACTIVE_ROW_FG = Color.rgb(0x1A, 0x3A, 0x8C);
    private static final Color SIDEBAR_BG = Color.rgb(0xF6, 0xF7, 0xFA);
    private static final Color BAR_BORDER = Color.rgb(0xE2, 0xE8, 0xF0);
    private static final Color BAR_BG = Color.rgb(0xFB, 0xFB, 0xFD);

    /** A track in the demo library (fictional albums; art is a local SVG asset). */
    private record Track(String title, String artist, String album, float duration, String cover) {}

    private static final List<Track> TRACKS = List.of(
            new Track("Midnight Drive", "The Neon Signals", "Neon Nights", 214f,
                    "/_pathland/assets/albumart/cover1.svg"),
            new Track("Glass Horizon", "The Neon Signals", "Neon Nights", 178f,
                    "/_pathland/assets/albumart/cover1.svg"),
            new Track("Static Bloom", "The Neon Signals", "Neon Nights", 224f,
                    "/_pathland/assets/albumart/cover1.svg"),
            new Track("Blue Hour", "Mara Voss", "Blue Hour", 192f,
                    "/_pathland/assets/albumart/cover2.svg"),
            new Track("Paper Moons", "Mara Voss", "Blue Hour", 167f,
                    "/_pathland/assets/albumart/cover2.svg"),
            new Track("Tidal", "Mara Voss", "Blue Hour", 222f,
                    "/_pathland/assets/albumart/cover2.svg"),
            new Track("Analog Heart", "The Weatherfield", "Analog Heart", 240f,
                    "/_pathland/assets/albumart/cover3.svg"),
            new Track("Slow Light", "The Weatherfield", "Analog Heart", 185f,
                    "/_pathland/assets/albumart/cover3.svg"),
            new Track("Night Bus", "The Weatherfield", "Analog Heart", 159f,
                    "/_pathland/assets/albumart/cover3.svg"));

    // App-owned, persisted per-session (the annotation processor wires State fields
    // by type; explicit keys keep the player's state scope stable).
    State<Float> position = new State<>(0f, "player.position");
    State<Boolean> playing = new State<>(false, "player.playing");
    State<Integer> trackIndex = new State<>(0, "player.track");
    State<Float> volume = new State<>(70f, "player.volume");

    @Override
    public View body() {
        var current = computed(() -> TRACKS.get(trackIndex.get() % TRACKS.size()));
        var elapsed = computed(() -> fmt(position.get()));
        var duration = computed(() -> fmt(current.get().duration()));
        var glyph = computed(() -> playing.get() ? "⏸" : "▶");

        return VStack.of(
                HStack.of(
                        library(),
                        nowPlayingSidebar(current)
                ).with(FrameMod.of(Commands.Size.FILL, Commands.Size.FILL, null)),
                playerBar(current, elapsed, duration, glyph)
        )
        .with(FrameMod.of(Commands.Size.FILL, Commands.Size.FILL, null))
        .with(AccessibilityRole.of(Roles.MAIN));
    }

    /** The library: a header and the full track list (rows stretch full width). */
    private View library() {
        List<View> rows = new ArrayList<>();
        for (int i = 0; i < TRACKS.size(); i++) {
            rows.add(trackRow(i));
        }
        return VStack.of(
                Text.of("Library").with(FontSize.of(26), FontWeightMod.of(FontWeight.BOLD))
                        .with(AccessibilityRole.of(Roles.HEADER)),
                Text.of(TRACKS.size() + " songs · 3 albums").with(ForegroundStyle.of(SECONDARY_FG)),
                Divider.of().with(Padding.of(0, 0, 0, 10)),
                VStack.of(rows)
        )
        .with(Padding.of(24))
        .with(FrameMod.of(Commands.Size.FILL, Commands.Size.FILL, null));
    }

    /** A single track row: cover thumb, title/artist, and duration; selecting it plays it. */
    private View trackRow(int i) {
        Track t = TRACKS.get(i);
        var isCurrent = computed(() -> trackIndex.get() % TRACKS.size() == i);
        var bg = computed(() -> isCurrent.get() ? ACTIVE_ROW_BG : Color.CLEAR);
        var fg = computed(() -> isCurrent.get() ? ACTIVE_ROW_FG : Color.BLACK);
        return Button.of(
                HStack.of(Alignment.CENTER, 12f,
                        Image.of(t.cover())
                                .with(FrameMod.of(44, 44, null), ScaledToFit.of()),
                        VStack.of(Alignment.LEADING, 2,
                                Text.of(t.title()).with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                                Text.of(t.artist() + " · " + t.album())
                                        .with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG))
                        ).with(FrameMod.of(Commands.Size.FILL, Float.NaN, null)),
                        Text.of(fmt(t.duration()))
                                .with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG))
                ),
                () -> select(i))
                .with(Background.of(bg), ForegroundStyle.of(fg))
                .with(Padding.of(6));
    }

    /** The right sidebar: large album art, now-playing title/artist, and "up next". */
    private View nowPlayingSidebar(Signal<Track> current) {
        return VStack.of(Alignment.LEADING, 14,
                Text.of("Now Playing").with(FontSize.of(18), FontWeightMod.of(FontWeight.BOLD))
                        .with(AccessibilityRole.of(Roles.HEADER)),
                Image.of(computed(() -> current.get().cover()))
                        .with(FrameMod.of(220, 220, Alignment.CENTER), ScaledToFit.of())
                        .with(Padding.of(0, 0, 0, 6)),
                Text.of(computed(() -> current.get().title()))
                        .with(FontSize.of(20), FontWeightMod.of(FontWeight.BOLD)),
                Text.of(computed(() -> current.get().artist() + " · " + current.get().album()))
                        .with(ForegroundStyle.of(SECONDARY_FG)),
                Divider.of().with(Padding.of(0, 0, 0, 10)),
                Text.of("Up Next").with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                upNextRow(1),
                upNextRow(2)
        )
        .with(Padding.of(24))
        .with(Background.of(SIDEBAR_BG))
        .with(FrameMod.of(SIDEBAR_WIDTH, Commands.Size.FILL, null));
    }

    private View upNextRow(int offset) {
        return Text.of(computed(() -> {
            Track t = TRACKS.get((trackIndex.get() + offset) % TRACKS.size());
            return (offset == 1 ? "Up next · " : "Then · ") + t.title() + " — " + t.artist();
        })).with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG));
    }

    /** The bottom player bar: transport controls, seek slider, and volume. */
    private View playerBar(Signal<Track> current, Signal<String> elapsed, Signal<String> duration,
                           Signal<String> glyph) {
        return HStack.of(Alignment.CENTER, 14f,
                Button.of("⏮", this::prev).with(FontSize.of(20)),
                Button.of(Text.of(glyph), () -> playing.update(v -> !v)).with(FontSize.of(28)),
                Button.of("⏭", this::next).with(FontSize.of(20)),
                VStack.of(Alignment.LEADING, 2,
                        Text.of(computed(() -> current.get().title()))
                                .with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                        Text.of(computed(() -> current.get().artist()))
                                .with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG))
                ).with(Padding.of(8, 20, 8, 20)).with(FrameMod.of(180f, Float.NaN, null)),
                Spacer.of(),
                Text.of(elapsed).with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG)),
                Slider.of(position.signal(), 0f, SEEK_MAX).with(FrameMod.of(240f, Float.NaN, null)),
                Text.of(duration).with(FontSize.of(13), ForegroundStyle.of(SECONDARY_FG)),
                Spacer.of(),
                Text.of("🔊").with(FontSize.of(16)),
                Slider.of(volume.signal(), 0f, VOLUME_MAX).with(FrameMod.of(96f, Float.NaN, null))
        )
        .with(Padding.of(12, 16, 12, 16))
        .with(Background.of(BAR_BG))
        .with(Border.of(BAR_BORDER, 1f, 0f))
        .with(FrameMod.of(Commands.Size.FILL, BAR_HEIGHT, null));
    }

    // --- playback control (app-owned state; no timers) ---

    private void select(int i) {
        trackIndex.set(i);
        position.set(0f);
        playing.set(true);
    }

    private void prev() {
        trackIndex.update(i -> (i - 1 + TRACKS.size()) % TRACKS.size());
        position.set(0f);
    }

    private void next() {
        trackIndex.update(i -> (i + 1) % TRACKS.size());
        position.set(0f);
    }

    /** Format seconds as {@code m:ss}. */
    private static String fmt(float seconds) {
        int s = Math.max(0, Math.round(seconds));
        return (s / 60) + ":" + String.format("%02d", s % 60);
    }
}

